import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.Logger;

@WebServlet("/api/admin/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());

    // Database connection pool configured via JNDI
    private static final String JNDI_NAME = "java:comp/env/jdbc/PrimaryDB";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, java.io.IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String searchField = req.getParameter("field");
        String searchValue = req.getParameter("value");
        String sortColumn = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (searchField == null || searchValue == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Whitelist allowed search fields
        String[] allowedFields = {"username", "email", "department", "status"};
        boolean fieldValid = false;
        for (String f : allowedFields) {
            if (f.equals(searchField)) { fieldValid = true; break; }
        }
        if (!fieldValid) {
            resp.sendError(400, "Invalid search field");
            return;
        }

        // Sort column validation - NOTE: sort is user-controlled
        if (sortColumn == null) sortColumn = "username";
        if (sortDir == null) sortDir = "ASC";

        // Build query - searchValue is parameterized but sortColumn is concatenated
        String query = "SELECT user_id, username, email, department, status " +
                       "FROM admin_users WHERE " + searchField + " LIKE ? " +
                       "ORDER BY " + sortColumn + " " + 
                       (sortDir.equalsIgnoreCase("DESC") ? "DESC" : "ASC");

        log.info("Executing search: field=" + searchField + ", sort=" + sortColumn);

        try {
            javax.naming.InitialContext ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup(JNDI_NAME);

            try (Connection conn = ds.getConnection();
                 PreparedStatement stmt = conn.prepareStatement(query)) {

                stmt.setString(1, "%" + searchValue + "%");

                ResultSet rs = stmt.executeQuery();
                StringBuilder json = new StringBuilder("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",");
                    json.append(String.format(
                        "{\"id\":%d,\"username\":\"%s\",\"email\":\"%s\",\"dept\":\"%s\",\"status\":\"%s\"}",
                        rs.getInt("user_id"), rs.getString("username"),
                        rs.getString("email"), rs.getString("department"),
                        rs.getString("status")));
                    first = false;
                }
                json.append("]");

                resp.setContentType("application/json");
                resp.getWriter().write(json.toString());
            }
        } catch (Exception e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean validateSession(String token) {
        // Validates against session store - implementation omitted
        return token != null && token.length() == 64;
    }
}
